func (q *Queries) MarkFiscalDocumentRetry(ctx context.Context, arg MarkFiscalDocumentRetryParams) (FiscalDocument, error) {
	row := q.db.QueryRow(ctx, markFiscalDocumentRetry, arg.ErrorMessage, arg.ID)
	var i FiscalDocument
	err := row.Scan(
		&i.ID,
		&i.CompanyID,
		&i.SaleID,
		&i.Model,
		&i.Environment,
		&i.Attempt,
		&i.IdempotencyKey,
		&i.ExternalID,
		&i.Status,
		&i.Number,
		&i.AccessKey,
		&i.Protocol,
		&i.StatusCode,
		&i.RejectReason,
		&i.ErrorMessage,
		&i.EmissionType,
		&i.AuthorizedAt,
		&i.CancelReason,
		&i.CancelledAt,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.RequestPayload,
		&i.Retries,
	)
	return i, err
}

